import numpy as np

def feature(item, bins, capacity):
    """Conditional on a large item: room left for a second large job plus a small one."""
    cap = np.asarray(capacity, dtype=float)
    L = 0.4 * cap
    s = 0.15 * cap
    r = bins - item  # remaining room after placing the job
    large = (item[0] >= 0.4 * cap[0]) or (item[1] >= 0.4 * cap[1])
    if not large:
        return np.zeros(bins.shape[0])
    fits_large = np.minimum(r[:, 0] / L[0], r[:, 1] / L[1]) >= 1.0
    extra = np.minimum((r[:, 0] - L[0]) / s[0], (r[:, 1] - L[1]) / s[1])
    return np.where(fits_large, np.clip(extra, 0.0, 1.0), 0.0)

