import numpy as np

def feature(item, bins, capacity):
    """For large items: does the residual after placing still fit a small job, scaled by how balanced it is."""
    cap = np.asarray(capacity, dtype=float)
    it = np.asarray(item, dtype=float)
    r = bins - it
    s = 0.15 * cap
    large = (it[0] >= 0.4 * cap[0]) or (it[1] >= 0.4 * cap[1])
    if not large:
        return np.zeros(bins.shape[0])
    fits = (r[:, 0] >= s[0]) & (r[:, 1] >= s[1])
    frac = np.maximum(r[:, 0] / cap[0], r[:, 1] / cap[1])
    return fits.astype(float) * (1.0 - frac)

